<!DOCTYPE html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Preview — Qammaris Journal</title>
<style>body{margin:0;background:#f7f6f2;font:15px system-ui;color:#202020}header{padding:12px 20px;display:flex;flex-wrap:wrap;align-items:center;gap:12px;border-bottom:1px solid #ddd}button{min-height:44px;padding:8px 16px;border:1px solid #aaa;background:white;cursor:pointer;touch-action:manipulation}button:focus-visible{outline:2px solid #202020}iframe{display:block;border:0;background:white;width:100%;height:calc(100vh - 100px);margin:0 auto;max-width:1440px}iframe.mobile{max-width:390px}button[aria-pressed=true]{background:#202020;color:white}p{margin:0}</style></head>
<body><header><strong>Preview · belum disimpan</strong><button type="button" aria-pressed="true" data-width="desktop">Desktop</button><button type="button" aria-pressed="false" data-width="mobile">Mobile</button><p>Tutup tab ini untuk kembali ke editor.</p></header>
<iframe title="Preview artikel" sandbox="allow-same-origin" srcdoc="{{ $html }}"></iframe>
<script>const frame=document.querySelector('iframe');document.querySelectorAll('button[data-width]').forEach(button=>button.addEventListener('click',()=>{frame.classList.toggle('mobile',button.dataset.width==='mobile');document.querySelectorAll('button[data-width]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));}));</script></body></html>
